tool.command:
@SHELL_OPTIONS@
## create symlinks to input datasets ln -s '$shared' shared.dat &&
echo 'make.clr( #if $label: label=${ str($label).replace(",","-") }, #end if #if $groups: groups=${ str($groups).replace(",","-") }, #end if zero=$zero, shared=shared.dat )' | sed 's/ //g; s/,)$/)/' ## mothur trips over whitespace; a trailing comma segfaults mothur >1.42 | mothur | tee mothur.out.log
